/* Base64 encoded Surya P. Resume PDF - guarantees instant download anywhere */
window.SURYA_RESUME_BASE64 = "";

function downloadSuryaResume(filename = "Surya_P_Resume.pdf") {
  try {
    const base64Data = window.SURYA_RESUME_BASE64;
    const byteCharacters = atob(base64Data);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: "application/pdf" });
    const blobUrl = URL.createObjectURL(blob);
    
    const tempLink = document.createElement("a");
    tempLink.href = blobUrl;
    tempLink.download = filename;
    tempLink.target = "_blank";
    document.body.appendChild(tempLink);
    tempLink.click();
    document.body.removeChild(tempLink);
    setTimeout(() => URL.revokeObjectURL(blobUrl), 2000);
  } catch (e) {
    window.open("assets/pdf/Surya_P_Resume.pdf", "_blank");
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const resumeLinks = document.querySelectorAll('a[href*="Surya_P_Resume.pdf"], #resume-btn, .resume-download-btn');
  resumeLinks.forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      downloadSuryaResume("Surya_P_Resume.pdf");
    });
  });
});